<section class="view hidden" id="view-clubs" data-title="Explore clubs" data-section="Student workspace">
  <div class="page-heading"><div><span class="eyebrow">FIND YOUR COMMUNITY</span><h1>Explore clubs</h1><p class="muted">Discover spaces to learn, create and connect.</p></div><button class="button button-primary" data-view="clubs">Explore clubs <span>→</span></button></div>
  <form class="toolbar" method="get" action="index.php"><input type="hidden" name="view" value="clubs"><div class="search-box"><span>⌕</span><input id="club-search" name="q" type="search" value="<?= e($_GET['q'] ?? '') ?>" placeholder="Search clubs..." aria-label="Search clubs"></div><div class="filter-pills" role="group" aria-label="Club category"><a class="filter-pill <?= empty($_GET['category']) ? 'active' : '' ?>" href="index.php?view=clubs">All clubs</a><?php foreach (['Academic', 'Creative', 'Social', 'Sports'] as $category): ?><a class="filter-pill <?= strtolower((string) ($_GET['category'] ?? '')) === strtolower($category) ? 'active' : '' ?>" href="index.php?view=clubs&amp;category=<?= rawurlencode($category) ?>"><?= e($category) ?></a><?php endforeach; ?></div><button class="button button-outline" type="submit">Search</button></form>
